from flask import Flask, request, jsonify
import marshal

app = Flask(__name__)

@app.route("/run_books", methods=["POST"])
def run_books():
    choices = request.form.get("choices")
    print(choices)

    success_msg = "Books run!"
    return jsonify({"success_msg": success_msg})

if __name__ == "__main__":
    app.run()
